//! Runtime window/taskbar icon (the exe icon is embedded via the resource script).

use eframe::egui::IconData;

const SIZE: u32 = 64;
const RGBA: &[u8] = include_bytes!("../../../assets/atropos-64.rgba");

/// The 64x64 window icon generated by `scripts/make-icon.ps1`.
pub fn window_icon() -> IconData {
    IconData {
        rgba: RGBA.to_vec(),
        width: SIZE,
        height: SIZE,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn icon_bytes_match_dimensions() {
        let icon = window_icon();
        assert_eq!(icon.rgba.len(), (SIZE * SIZE * 4) as usize);
    }
}
